UPDATE glossary_terms SET description_ko='대한민국의 대표 국가스카우트조직(NSO)이다. 원문 조직명은 Korea Scout Association이다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=1 AND bucket IS '하' AND term_ko IS '한국스카우트연맹' AND term_en IS 'Korea Scout Association' AND term_fr IS '-' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:31:28';
UPDATE glossary_terms SET description_ko='스카우트가 목에 두르는 항건이다. 단위대·지역·행사 등의 소속과 정체성을 나타내며, 색상과 착용 방법은 각 연맹의 제복 규정에 따른다.',updated_at=datetime('now') WHERE id=2 AND bucket IS '하' AND term_ko IS '항건' AND term_en IS 'Neckerchief' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:37:50';
UPDATE glossary_terms SET description_ko='특정 분야의 지식과 기능을 배우고 정해진 성취 기준을 충족했음을 인정하는 배지이다. 종목과 취득 요건은 각 국가연맹의 프로그램에 따라 다르다.',updated_at=datetime('now') WHERE id=3 AND bucket IS '가' AND term_ko IS '기능장' AND term_en IS 'Merit Badge' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:41:21';
UPDATE glossary_terms SET description_ko='해당 스카우트 지역의 회원 조직 대표들이 모여 지역 차원의 정책과 방향을 논의하는 총회이다. 세계스카우트총회와 구분한다.',updated_at=datetime('now') WHERE id=5 AND bucket IS '자' AND term_ko IS '지역 총회' AND term_en IS 'Regional Conference' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:42:09';
UPDATE glossary_terms SET description_ko='지역 총회의 결의와 지역 차원의 운영 방향을 추진하는 스카우트 거버넌스 기구이다. 구성과 선출 방식은 해당 지역 규정에 따른다.',updated_at=datetime('now') WHERE id=6 AND bucket IS '자' AND term_ko IS '지역 이사회' AND term_en IS 'Regional Committee' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:42:19';
UPDATE glossary_terms SET description_ko='세계스카우트연맹의 최고 의사결정 총회이다. 회원 국가스카우트조직의 대표들이 정책·전략·주요 결의와 세계스카우트이사회 선출 등을 논의한다. 세계스카우트이사회 및 사무국과 구분한다.',updated_at=datetime('now') WHERE id=8 AND bucket IS '사' AND term_ko IS '세계총회' AND term_en IS 'World Scout Conference' AND term_fr IS 'Conférence Mondiale du Scoutisme' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-15 01:57:32';
UPDATE glossary_terms SET term_en='World Association of Girl Guides and Girl Scouts (WAGGGS)',updated_at=datetime('now') WHERE id=9 AND bucket IS '사' AND term_ko IS '세계걸스카우트연맹' AND term_en IS 'World Association of Girl Guides and Girl Scouts (WAGGS)' AND term_fr IS '' AND description_ko IS '전 세계 걸가이드와 걸스카우트 연맹이 가입한 국제 연맹으로, 여성과 소녀를 위한 스카우트 운동을 대표하는 국제기구이다. 1928년에 설립되었으며, 각 회원국을 통해 소녀와 청년 여성이 리더십, 시민성, 공동체 참여를 배우도록 지원하는 교육 프로그램을 운영하고 있다. “Girl Guide”라는 명칭은 스카우트 운동이 시작된 초기 역사와 관련이 있다. 1909년 영국의 스카우트 집회에 소녀들이 참여하면서 여성 청소년을 위한 별도의 프로그램이 필요해졌고, 로버트 베이든파월은 여동생 아그네스 베이든파월과 함께 소녀들을 위한 단체를 조직하였다. 이때 소녀 단체는 남성 중심의 “Scout” 대신 “Guide”라는 명칭을 사용하게 되었는데, 이는 길을 찾고 다른 사람을 이끄는 역할을 상징하는 표현이었다. 이후 여러 국가에서는 “Girl Guides”라는 명칭을 사용하게 되었고, 일부 국가에서는 “Girl Scouts”라는 명칭이 함께 사용되었다. 이러한 역사적 배경 때문에 세계 연맹의 명칭도 Girl Guides와 Girl Scouts를 함께 사용한 “World Association of Girl Guides and Girl Scouts” 형태로 구성되어 있다.' AND sort_order IS 0 AND updated_at IS '2026-03-16 08:10:57';
UPDATE glossary_terms SET term_en='World Organization of the Scout Movement (WOSM)',description_ko='국가스카우트조직(NSO)을 회원으로 하는 세계 스카우트운동의 국제 조직이다. 청소년의 교육과 성장을 지원하며, 세계스카우트총회·세계스카우트이사회·세계스카우트사무국을 중심으로 운영된다. WAGGGS와는 별개의 국제 조직이다.',updated_at=datetime('now') WHERE id=10 AND bucket IS '사' AND term_ko IS '세계스카우트연맹' AND term_en IS 'World Organization of Scout Movement (WOSM)' AND term_fr IS 'Organisation Mondiale du Mouvement Scout' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-05-28 10:21:05';
UPDATE glossary_terms SET description_ko='각국 스카우트의 최고 급위 또는 이에 준하는 성취를 이룬 이들이 교류하고 스카우트 정신과 봉사를 이어가는 네트워크이다. 최고 급위의 명칭과 인정 기준은 국가마다 다르다.',updated_at=datetime('now') WHERE id=11 AND bucket IS '사' AND term_ko IS '세계최고급위진급자모임' AND term_en IS 'Association of Top/Achiever Scout (ATAS)' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:50:20';
UPDATE glossary_terms SET description_ko='한국의 범스카우트들이 교류하며 스카우트 정신과 봉사 활동을 이어가는 조직이다. 범스카우트의 진급 기준과 이 조직의 회원 활동은 구분하여 이해한다.',updated_at=datetime('now') WHERE id=13 AND bucket IS '하' AND term_ko IS '한국범스카우트중앙회' AND term_en IS 'Tiger Scout Association of Korea (TSAK)' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:51:33';
UPDATE glossary_terms SET description_ko='한 국가연맹의 국제 업무와 다른 국가연맹·국제 스카우트 기구와의 협력을 담당하는 직책이다. 권한과 임명 방식은 소속 연맹 규정에 따른다.',updated_at=datetime('now') WHERE id=14 AND bucket IS '가' AND term_ko IS '국제커미셔너' AND term_en IS 'International Commissioner' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:53:03';
UPDATE glossary_terms SET description_ko='스카우트 성인지도자 훈련을 지원하는 훈련 담당자의 자격·직책이다. 한국어 명칭과 세부 역할은 한국스카우트연맹의 현행 훈련 규정에 따른다.',updated_at=datetime('now') WHERE id=15 AND bucket IS '하' AND term_ko IS '훈련부교수' AND term_en IS 'Assistant Leader Trainer (ALT)' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:53:29';
UPDATE glossary_terms SET description_ko='스카우트 지도자의 교육과 훈련을 담당하는 훈련 담당자의 자격·직책이다. 세부 역할과 자격 요건은 해당 연맹의 현행 훈련 규정에 따른다.',updated_at=datetime('now') WHERE id=16 AND bucket IS '하' AND term_ko IS '훈련교수' AND term_en IS 'Leader Trainer (LT)' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:53:38';
UPDATE glossary_terms SET description_ko='스카우트 지도자 훈련 담당자를 준비하는 과정이다. 과정 명칭·참가 자격·인증 기준은 해당 연맹의 현행 지도자 훈련 규정에서 확인한다.',updated_at=datetime('now') WHERE id=17 AND bucket IS '하' AND term_ko IS '훈련부교수과정' AND term_en IS 'Course for Assistant Leader Trainers (CALT)' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:54:05';
UPDATE glossary_terms SET description_ko='스카우트 지도자 훈련 담당자의 역량을 기르는 과정이다. 운영 방식과 수료 요건은 해당 연맹의 현행 지도자 훈련 규정에 따른다.',updated_at=datetime('now') WHERE id=18 AND bucket IS '하' AND term_ko IS '훈련교수과정' AND term_en IS 'Course for Leader Trainers (CLT)' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:54:31';
UPDATE glossary_terms SET term_en='International Challenge Award',description_ko='국제 교류 활동에 대한 성취를 인정하는 포상 명칭이다. 여기의 영문은 용어 표기이며, 수여 대상·요건은 수여 연맹의 현행 포상 규정에서 확인한다.',updated_at=datetime('now') WHERE id=19 AND bucket IS '가' AND term_ko IS '국제교류장' AND term_en IS 'Internatioanl Challenge Award' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:55:08';
UPDATE glossary_terms SET description_ko='국제 봉사 활동과 관련된 공헌을 인정하는 포상 명칭이다. 수여 대상과 세부 요건은 수여 연맹의 현행 포상 규정에 따른다.',updated_at=datetime('now') WHERE id=20 AND bucket IS '가' AND term_ko IS '국제봉사장' AND term_en IS 'International Service Award' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:55:23';
UPDATE glossary_terms SET description_ko='스카우트 훈련과 관련된 봉사·공헌을 인정하는 포상 명칭이다. 영문 표기만으로 다른 국가의 동명 포상과 동일한 제도라고 판단하지 않으며, 세부 요건은 수여 연맹 규정에서 확인한다.',updated_at=datetime('now') WHERE id=21 AND bucket IS '하' AND term_ko IS '훈련봉사장' AND term_en IS 'Impeesa Award' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:55:31';
UPDATE glossary_terms SET description_ko='청소년의 모범적인 활동과 성취를 인정하는 시상 명칭이다. 수상 부문·추천 방식·자격은 해당 연도 주최 기관의 공고에서 확인한다.',updated_at=datetime('now') WHERE id=22 AND bucket IS '자' AND term_ko IS '자랑스러운 청소년대상' AND term_en IS 'Youth Hero' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:56:35';
UPDATE glossary_terms SET description_ko='한국스카우트연맹이 주관하는 전국 규모의 스카우트 야영 행사이다. 국제 대표단이 함께 참가할 수 있으며, 개최 일정·장소·참가 기준은 회차별 공고를 따른다.',updated_at=datetime('now') WHERE id=23 AND bucket IS '하' AND term_ko IS '한국잼버리' AND term_en IS 'Korea National Jamboree' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:58:01';
UPDATE glossary_terms SET description_ko='스카우트가 스스로 약속하고 생활 속에서 실천하는 가치 기준이다. 선서는 개인의 다짐이고 규율은 일상적인 행동 지침이며, 구체적인 문구는 각 국가연맹에 따라 다를 수 있다.',updated_at=datetime('now') WHERE id=24 AND bucket IS '사' AND term_ko IS '스카우트 선서와 규율' AND term_en IS 'The Scout Promise and Law' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:58:58';
UPDATE glossary_terms SET description_ko='활동을 직접 해 보고 그 경험을 돌아보며 배우는 스카우트 방법론의 요소이다. 실천과 성찰을 연결하여 지식·기능·태도를 기른다.',updated_at=datetime('now') WHERE id=25 AND bucket IS '하' AND term_ko IS '행하면서 배우기' AND term_en IS 'Learning by Doing' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:59:14';
UPDATE glossary_terms SET description_ko='청소년이 자신의 목표를 세우고 경험과 성취를 돌아보며 단계적으로 성장하도록 돕는 스카우트 방법론의 요소이다. 배지나 급위만으로 한정되지 않는다.',updated_at=datetime('now') WHERE id=26 AND bucket IS '자' AND term_ko IS '진보 제도' AND term_en IS 'Personal Progression' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:59:24';
UPDATE glossary_terms SET description_ko='청소년이 작은 팀에서 역할과 책임을 나누고 서로 협력하며 배워 가는 스카우트 방법론의 요소이다. 패트롤 제도와 연결되며 팀의 의사결정과 공동 활동을 중시한다.',updated_at=datetime('now') WHERE id=27 AND bucket IS '바' AND term_ko IS '반 제도' AND term_en IS 'Team System' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:59:34';
UPDATE glossary_terms SET description_ko='성인이 청소년의 안전과 성장을 지원하면서 청소년이 주도적으로 배우고 활동할 수 있도록 돕는 스카우트 방법론의 요소이다. 성인이 모든 결정을 대신하는 방식과 구분한다.',updated_at=datetime('now') WHERE id=28 AND bucket IS '사' AND term_ko IS '성인 인적자원 지원' AND term_en IS 'Adult Support' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 07:59:45';
UPDATE glossary_terms SET description_ko='자연 속 활동과 경험을 통해 자신과 환경을 이해하고 책임감을 기르는 스카우트 방법론의 요소이다. 야외 활동뿐 아니라 자연과의 관계와 환경 보호를 포함한다.',updated_at=datetime('now') WHERE id=30 AND bucket IS '자' AND term_ko IS '자연' AND term_en IS 'Nature' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:00:03';
UPDATE glossary_terms SET description_ko='청소년이 지역사회의 필요를 이해하고 다른 사람들과 협력하여 공동체에 기여하는 스카우트 방법론의 요소이다. 단순한 일회성 봉사 시간을 넘어 배움과 참여를 연결한다.',updated_at=datetime('now') WHERE id=31 AND bucket IS '자' AND term_ko IS '지역사회 참여' AND term_en IS 'Community Involvement' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:00:13';
UPDATE glossary_terms SET description_ko='청소년의 점진적인 자기교육을 지원하는 스카우트운동의 교육 체계이다. 선서와 규율, 행하면서 배우기, 개인의 진보, 팀 제도, 성인의 지원, 상징 체계, 자연, 지역사회 참여의 8개 요소가 서로 연결되어 작동한다.',updated_at=datetime('now') WHERE id=32 AND bucket IS '사' AND term_ko IS '스카우트방법론' AND term_en IS 'The Scout Method' AND term_fr IS 'Méthode Scoute' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-15 02:00:15';
UPDATE glossary_terms SET description_ko='아시아태평양지역연맹과 개최국 국가스카우트조직이 협력하여 개최하는 국제 스카우트 야영 행사이다. 지역의 청소년이 프로그램, 야외 활동, 문화 교류를 함께 경험한다. 세계스카우트잼버리 및 각국의 전국 잼버리와 구분하며, 개최 연도·장소·참가 조건은 해당 회차 공식 공고를 기준으로 확인한다.',updated_at=datetime('now') WHERE id=33 AND bucket IS '아' AND term_ko IS '아시아태평양지역 스카우트 잼버리' AND term_en IS 'Asia-Pacific Regional Scout Jamboree' AND term_fr IS '' AND description_ko IS '세계연맹 아·태 사무처(필리핀 마닐라/33개 회원국)에서 주관하는 스카우트 국제행사입니다. 1973년에 필리핀에서 첫 번째 아시아태평양지역 스카우트 잼버리(이하 아·태 잼버리)가 개최되었습니다. 잼버리 개최지는 아시아태평양지역 총회를 통해 회원국에서 잼버리 유치 신청하고, 아·태 연맹에서 검토하여 승인, 유치가 결정되면 아·태 사무처와 유치 국가연맹이 공동으로 잼버리를 운영합니다. 가장 최근 2023년 1월 방글라데시에서 제32회 아·태 잼버리가 개최되었습니다. 한국스카우트연맹은 제8회(1982년), 제17회(1996년), 제21회(2000년), 제24회(2004년), 제27회(2010년) 총 5회 개최하였습니다.' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:01:43';
UPDATE glossary_terms SET description_ko='한 국가의 스카우트 조직이 주관하는 전국 규모의 잼버리이다. 국내 대원을 중심으로 운영하되 해외 대표단을 초청할 수도 있다. 개최 간격과 참가 연령은 국가·회차별로 달라 모든 국가가 같은 주기로 개최하는 것은 아니다. 세계잼버리·지역잼버리와 구분한다.',updated_at=datetime('now') WHERE id=34 AND bucket IS '자' AND term_ko IS '전국 잼버리' AND term_en IS 'National Jamboree' AND term_fr IS '' AND description_ko IS '세계연맹에 소속되어 있는 각 회원국(176개 회원국)이 주관하는 스카우트 국제행사입니다. 한국은 2년마다 한국잼버리(4년)와 국제패트롤잼버리(4년)를 개최하고 있습니다. 대부분의 회원국은 자국연맹에 2~4년 간격으로 국가 잼버리를 개최합니다. 잼버리의 규모에 따라 자국 스카우트뿐만 아니라 해외 스카우트를 참가자로 초대(초청)하여 함께 잼버리를 즐기기도 합니다. 단, 국가 잼버리를 개최하면서 동시에 아·태 잼버리를 유치하게 되면 상위 행사의 명칭을 앞에 사용합니다.' AND sort_order IS 0 AND updated_at IS '2026-06-24 01:08:50';
UPDATE glossary_terms SET description_ko='패트롤을 중심으로 팀 활동과 국제 교류를 경험하는 잼버리 형태이다. 국내 행사로 사용되는 경우 개최 주체·참가 구성·운영 주기는 해당 회차의 공식 안내를 따른다.',updated_at=datetime('now') WHERE id=35 AND bucket IS '가' AND term_ko IS '국제패트롤잼버리' AND term_en IS 'International Patrol Jamboree' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:04:42';
UPDATE glossary_terms SET description_ko='컵스카우트보다 어린 연령층을 위한 스카우트 단계의 명칭이다. 운영 여부와 연령 범위는 국가연맹마다 다르며 모든 국가에서 같은 기준으로 운영되는 것은 아니다.',updated_at=datetime('now') WHERE id=36 AND bucket IS '바' AND term_ko IS '비버스카우트 (유아대)' AND term_en IS 'Beaver Scouts' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:15:53';
UPDATE glossary_terms SET description_ko='어린이 연령층을 위한 스카우트 단계이다. 놀이, 이야기, 야외 활동과 협동 경험을 통해 성장하며, 연령과 진급 체계는 각 국가연맹의 프로그램에 따른다.',updated_at=datetime('now') WHERE id=37 AND bucket IS '카' AND term_ko IS '컵스카우트(유년대)' AND term_en IS 'Cub Scouts' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:15:44';
UPDATE glossary_terms SET description_ko='청소년이 패트롤 활동, 야영, 탐험과 다양한 성취 활동을 통해 책임감과 협동심을 기르는 스카우트 단계이다. 구체적인 연령 범위는 국가연맹별로 다르다.',updated_at=datetime('now') WHERE id=38 AND bucket IS '사' AND term_ko IS '스카우트 (소년대)' AND term_en IS 'Scouts' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:15:24';
UPDATE glossary_terms SET description_ko='스카우트 이후 연령층을 대상으로 도전 활동, 리더십과 사회 참여를 강조하는 단계의 명칭이다. 국가에 따라 Venture 또는 Venturer 등의 표기와 다른 연령 기준을 사용한다.',updated_at=datetime('now') WHERE id=39 AND bucket IS '바' AND term_ko IS '벤처스카우트 (청년대)' AND term_en IS 'Venture Scouts' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:19:22';
UPDATE glossary_terms SET term_en='Chief Commissioner',description_ko='스카우트 조직의 프로그램·지도자 활동을 총괄하거나 조정하는 커미셔너 직책이다. 국가·지역의 조직 구조에 따라 역할과 권한이 다르다.',updated_at=datetime('now') WHERE id=40 AND bucket IS '차' AND term_ko IS '치프커미셔너' AND term_en IS 'Cheif Commissioner' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:13:09';
UPDATE glossary_terms SET term_en='National Chief Commissioner',description_ko='국가 수준에서 스카우트 프로그램과 지도자 활동을 총괄하거나 조정하는 치프커미셔너 직책이다. 구체적인 권한·임명 방식은 해당 국가연맹의 규정에 따른다.',updated_at=datetime('now') WHERE id=41 AND bucket IS '자' AND term_ko IS '중앙치프커미셔너' AND term_en IS 'National Cheif Commissioner' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:13:17';
UPDATE glossary_terms SET description_ko='국가연맹 차원에서 맡은 분야의 스카우트 활동과 지도자 업무를 조정·지원하는 커미셔너 직책이다. 모든 연맹에서 같은 직무를 뜻하는 것은 아니다.',updated_at=datetime('now') WHERE id=42 AND bucket IS '자' AND term_ko IS '중앙커미셔너' AND term_en IS 'National Commissioner' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:13:23';
UPDATE glossary_terms SET description_ko='세계스카우트연맹의 집행·운영 이사회이다. 세계스카우트총회의 결의를 실행하고 총회 사이에 세계 스카우트운동의 운영을 맡는다. 세계총회 및 사무국과 구분한다.',updated_at=datetime('now') WHERE id=45 AND bucket IS '사' AND term_ko IS '세계스카우트이사회' AND term_en IS 'World Scout Committee' AND term_fr IS 'Comité Mondial du Scoutisme' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-15 02:01:46';
UPDATE glossary_terms SET description_ko='스카우트가 지역사회에서 대화, 상호 이해, 봉사와 평화를 위한 활동을 기획하고 실천하도록 지원하는 세계스카우트연맹의 국제 이니셔티브이다. 공동체의 필요를 파악하고 협력하여 긍정적인 변화를 만드는 데 초점을 둔다. 프로젝트 수와 봉사 시간 등 누적 실적은 집계 시점에 따라 달라지므로 최신 공식 자료를 별도로 확인한다.',updated_at=datetime('now') WHERE id=46 AND bucket IS '파' AND term_ko IS '평화의 메신저' AND term_en IS 'Messengers of Peace' AND term_fr IS '' AND description_ko IS 'Messengers of Peace(평화의 메신저)는 2010년 세계스카우트연맹이 시작한 글로벌 프로젝트로, 청소년 스카우트들이 지역사회에서 평화와 긍정적 변화를 만들기 위한 활동에 참여하도록 돕는 프로그램이다. 이 프로그램은 관용, 상호 이해, 지속가능한 발전을 촉진하는 다양한 지역사회 프로젝트를 청소년이 직접 기획하고 실행하도록 장려한다. 사우디아라비아 왕국의 지원을 바탕으로 전 세계 스카우트가 지역사회와 협력해 대화와 협력의 문화를 확산하고 있으며, 지금까지 1,600만 건 이상의 프로젝트가 진행되고 약 30억 시간에 가까운 지역사회 봉사 활동이 이루어졌다. (2026년 03월 기준)' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:29:35';
UPDATE glossary_terms SET description_ko='세계스카우트연맹(WOSM)의 사무국으로, 세계스카우트총회와 세계스카우트이사회의 활동을 행정적·실무적으로 지원한다. 세계스카우트이사회가 임명한 사무총장(Secretary General)이 이끌며, 국가스카우트조직에 대한 지원, 세계 스카우트 행사 협력, 국제 파트너십과 운영 계획 실행을 담당한다.',updated_at=datetime('now') WHERE id=48 AND bucket IS '사' AND term_ko IS '세계스카우트연맹 사무국' AND term_en IS 'World Scout Bureau' AND term_fr IS 'Bureau Mondial du Scoutisme' AND description_ko IS '세계스카우트연맹의 사무국 역할을 하는 국제 운영 조직이다. 세계스카우트위원회가 임명하는 사무총장(Secretary General)이 최고 책임자로서 이 조직을 이끌며, 세계 스카우트운동의 이익을 보호하고 발전시키는 임무를 서행한다. 세계스카우트사무국은 세계 스카우트 행사 운영을 지원하고, 다양한 국제기구와의 협력을 통해 스카우트운동의 교육적 사명을 확장하는 역할을 한다. 또한 세계스카우트총회(World Scout Conference)와 세계스카우트이사회(World Scout Committee)의 활동을 행정적으로 지원하며, Strategy for Scouting에 따른 운영 계획을 자원봉사자들과 함께 실행한다. 이와 함께 세계 각국 회원국을 대상으로 WOSM Services 등 다양한 지원 프로그램을 제공하여 스카우트 활동의 발전을 돕고, 아직 스카우트운동이 활성화되지 않은 국가나 지역으로의 확장도 지원하고 있다.' AND sort_order IS 0 AND updated_at IS '2026-03-15 02:02:04';
UPDATE glossary_terms SET bucket='마',term_ko='무선·인터넷 잼버리 (JOTA-JOTI)',updated_at=datetime('now') WHERE id=49 AND bucket IS '가' AND term_ko IS '' AND term_en IS 'JOTA-JOTI' AND term_fr IS '' AND description_ko IS 'JOTA-JOTI(Jamboree on the Air – Jamboree on the Internet)는 전 세계 스카우트가 아마추어 무선통신과 인터넷을 통해 서로 연결되는 세계 최대 규모의 디지털 스카우트 행사이다. 이 행사는 스카우트들이 국경과 문화를 넘어 교류하며 글로벌 시민의식을 배우도록 돕는 국제 프로그램으로, 매년 수백만 명의 청소년이 참여한다. 참가자들은 무선 교신과 온라인 활동을 통해 다른 나라 스카우트들과 소통하며 우정과 문화 이해를 넓히고, 전통적인 스카우트 기술과 21세기 디지털 역량을 함께 경험하게 된다.' AND sort_order IS 0 AND updated_at IS '2026-03-14 08:37:48';
UPDATE glossary_terms SET term_en='Certificate of Volunteer Service',description_ko='봉사 활동에 참여한 사실을 확인하는 문서이다. 활동 기간·내용·시간과 확인 기관 등은 발급 기관의 양식에 따른다. 감사장(Certificate of Appreciation)과 구분한다.',updated_at=datetime('now') WHERE id=51 AND bucket IS '바' AND term_ko IS '봉사활동확인서' AND term_en IS 'Certificate of Apprecation' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 09:00:56';
UPDATE glossary_terms SET description_ko='특정 행사나 프로그램에 참가한 사실을 증명하는 문서이다. 교육 이수나 자격 취득을 증명하는 수료증·자격증과 구분한다.',updated_at=datetime('now') WHERE id=52 AND bucket IS '차' AND term_ko IS '참가증명서' AND term_en IS 'Certificate of Participation' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 09:01:42';
UPDATE glossary_terms SET description_ko='어떤 직책이나 역할에 임명되었음을 확인하는 문서이다. 임명 기간과 권한 범위는 임명 기관의 규정과 문서에 따른다.',updated_at=datetime('now') WHERE id=53 AND bucket IS '아' AND term_ko IS '임명장' AND term_en IS 'Certificate of Appointment' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 09:01:24';
UPDATE glossary_terms SET description_ko='스카우트 활동에서 우정과 교류의 상징으로 사용하는 장식 매듭의 명칭이다. 항건 등에 활용하며 안전 확보용 매듭으로 사용하지 않는다.',updated_at=datetime('now') WHERE id=54 AND bucket IS '아' AND term_ko IS '우정매듭' AND term_en IS 'Friendship Knot' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 09:08:14';
UPDATE glossary_terms SET description_ko='끈을 이용하여 막대나 목재 등 여러 부재를 결합하는 스카우트 개척 기술이다. 구조와 하중에 맞는 얽기 방법을 선택해야 하며 고소·중량 구조물에는 별도의 안전 검토가 필요하다.',updated_at=datetime('now') WHERE id=56 AND bucket IS '아' AND term_ko IS '얽기' AND term_en IS 'Lashing' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 09:09:16';
UPDATE glossary_terms SET description_ko='두 줄의 끝을 맞묶는 기본 매듭으로 Reef Knot이라고도 한다. 하중이 걸리는 안전 확보나 구조 작업에 적합한 매듭으로 간주하지 않는다.',updated_at=datetime('now') WHERE id=57 AND bucket IS '마' AND term_ko IS '맞매듭' AND term_en IS 'Square Knot' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 09:09:39';
UPDATE glossary_terms SET description_ko='스카우트 진급 체계에서 사용하는 급위 명칭이다. 취득 요건과 진급 순서는 해당 국가연맹의 현행 대원 프로그램에 따른다.',updated_at=datetime('now') WHERE id=58 AND bucket IS '가' AND term_ko IS '2급스카우트' AND term_en IS 'Second Class Scout' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 09:10:59';
UPDATE glossary_terms SET description_ko='스카우트 진급 체계에서 사용하는 급위 명칭이다. 동일한 영문 급위를 쓰더라도 국가별 기준이 다르므로 해당 연맹의 요건을 확인한다.',updated_at=datetime('now') WHERE id=59 AND bucket IS '가' AND term_ko IS '1급스카우트' AND term_en IS 'First Class Scout' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-14 09:10:53';
UPDATE glossary_terms SET term_en='Scouts of the World Award (SWA)',description_ko='청년이 평화·환경·지속가능한 발전과 관련된 지역사회 문제를 탐구하고 봉사 프로젝트를 실천하는 세계스카우트연맹의 국제 활동 인증이다. 기본 과정은 탐구(Discovery, 최소 21시간), 자원봉사(Volunteering, 최소 80시간), 네트워크 참여로 구성된다. 참가 조건과 운영 방식은 각 국가스카우트조직의 시행 안내를 함께 확인한다.',updated_at=datetime('now') WHERE id=60 AND bucket IS '사' AND term_ko IS '세계스카우트상' AND term_en IS 'Scouts Of the World Award (SOWA)' AND term_fr IS '' AND description_ko IS '주로 로버스카우트를 대상으로 하는 국제 프로그램이다. 이 상은 참가자가 평화(Peace), 환경(Environment), 지속가능성(Sustainability) 가운데 한 가지 주제를 선택해 프로젝트를 기획하고 실행하도록 장려하는 스카우트 활동 인증이다. 참가자는 최소 80시간 이상의 프로젝트 활동을 수행하며 지역사회, 국가 또는 국제사회에 지속적인 긍정적 영향을 줄 수 있는 활동을 진행한다. 이 과정에서 참가자는 프로젝트 관리, 팀워크, 예산 관리, 의사소통 등 다양한 역량을 기르고 유엔 지속가능발전목표(SDGs)에 대한 이해도 함께 높이게 된다.' AND sort_order IS 0 AND updated_at IS '2026-03-14 09:14:35';
UPDATE glossary_terms SET term_ko='영국 스카우트연맹',description_ko='영국의 대표 국가스카우트조직(NSO)이다. 원문 명칭은 The Scout Association이며 영국의 스카우트 프로그램과 지도자 활동을 지원한다. 소속 지역연맹: 유럽지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=63 AND bucket IS '아' AND term_ko IS '영국스카우트연맹' AND term_en IS 'The Scout Association' AND term_fr IS '' AND description_ko IS '영국스카우트연맹. 1907년 스카우트운동이 영국에서 시작되면서 창설된 스카우트 연맹으로, 회원국 명칭에 국가명을 포함하지 않는 사실상 유일한 사례로 알려져 있다. 현재 영국 전역의 스카우트 활동을 대표하는 조직이다.' AND sort_order IS 0 AND updated_at IS '2026-03-15 01:40:43';
UPDATE glossary_terms SET description_ko='미국을 대표하는 국가스카우트조직(NSO)이다. Boy Scouts of America(BSA)는 2024년 새 명칭을 발표했고, 2025년 2월 8일부터 Scouting America라는 명칭을 공식 사용한다. 회원국 현황의 옛 명칭과 현재 명칭은 같은 조직을 가리킨다. 소속 지역연맹: 인터아메리카지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=64 AND bucket IS '마' AND term_ko IS '미국 스카우트연맹' AND term_en IS 'Scouting America' AND term_fr IS '' AND description_ko IS '1910년 창설된 미국의 스카우트 연맹으로, 오랫동안 ‘Boy Scouts of America(BSA)’라는 명칭을 사용해 왔으며 2024년 명칭을 Scouting America로 변경하였다. 이는 모든 청소년에게 열린 스카우트운동의 포용적 방향성을 반영하기 위한 변화로, 미국 전역의 스카우트 활동을 대표한다.' AND sort_order IS 0 AND updated_at IS '2026-03-16 08:02:09';
UPDATE glossary_terms SET description_ko='스카우트의 소속과 정체성을 나타내는 복장이다. 활동 안전성과 기능성을 함께 고려하며, 구성·표장·착용 방법은 소속 연맹의 제복 규정에 따른다.',updated_at=datetime('now') WHERE id=65 AND bucket IS '자' AND term_ko IS '제복' AND term_en IS 'Uniform' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-15 01:41:59';
UPDATE glossary_terms SET description_ko='스위스 켄더스텍에 위치한 켄더스텍 국제스카우트센터(Kandersteg International Scout Centre, KISC)에서 봉사하거나 근무하는 국제 스태프를 가리키는 명칭이다. 세계잼버리의 국제 운영요원(IST)과는 별도의 센터 스태프 체계이다. KISC 스태프들이 전통적으로 분홍색 유니폼을 착용하는 데서 ‘Pinkie’라는 이름이 유래하였다.

Pinkie는 세계 각국의 스카우트가 일정 기간 센터에 봉사하며 운영을 지원하는 스태프로, 프로그램 운영, 숙소 및 캠프장 관리, 식당·케이터링 운영, 시설 유지관리, 활동 지원 등 센터의 일상적인 운영 전반을 담당한다.

스태프 형태는 보통 3개월 단위로 활동하는 단기 스태프(Short-Term Staff), 장기 스태프(Long-Term Staff), 여름 성수기에 운영되는 하이시즌 스태프(High Season Staff) 등으로 구분된다. Pinkie는 단순한 직원이 아니라 세계 각국의 스카우트가 함께 생활하며 봉사하는 국제 공동체의 일원이라는 의미로도 사용된다.',updated_at=datetime('now') WHERE id=67 AND bucket IS '파' AND term_ko IS '핑키 (켄더스텍 봉사자)' AND term_en IS 'Pinkie' AND term_fr IS '' AND description_ko IS '스위스 켄더스텍에 위치한 켄더스텍 국제스카우트센터(Kandersteg International Scout Centre, KISC)에서 근무하는 IST를 가리키는 명칭이다. KISC 스태프들이 전통적으로 분홍색 유니폼을 착용하는 데서 ‘Pinkie’라는 이름이 유래하였다.

Pinkie는 세계 각국의 스카우트가 일정 기간 센터에 봉사하며 운영을 지원하는 스태프로, 프로그램 운영, 숙소 및 캠프장 관리, 식당·케이터링 운영, 시설 유지관리, 활동 지원 등 센터의 일상적인 운영 전반을 담당한다.

스태프 형태는 보통 3개월 단위로 활동하는 단기 스태프(Short-Term Staff), 장기 스태프(Long-Term Staff), 여름 성수기에 운영되는 하이시즌 스태프(High Season Staff) 등으로 구분된다. Pinkie는 단순한 직원이 아니라 세계 각국의 스카우트가 함께 생활하며 봉사하는 국제 공동체의 일원이라는 의미로도 사용된다.' AND sort_order IS 0 AND updated_at IS '2026-03-15 02:09:09';
UPDATE glossary_terms SET term_en='International Service Team (IST)',updated_at=datetime('now') WHERE id=68 AND bucket IS '가' AND term_ko IS '국제 운영요원' AND term_en IS 'International Service STAFF (IST)' AND term_fr IS '' AND description_ko IS '국제 스카우트 행사에서 프로그램과 운영을 지원하기 위해 구성되는 국제 운영요원을 의미한다. IST는 세계 각국의 스카우트 지도자와 성인 스카우트로 구성되며, 참가자가 아니라 행사를 운영하고 지원하는 역할을 수행한다. IST는 세계스카우트잼버리, 지역 잼버리, 무트(Moot) 등 다양한 국제 행사에서 활동하며, 프로그램 운영, 참가자 지원, 시설 관리, 안전 운영, 행정 지원, 미디어, 물자 운영 등 행사 전반의 실무를 담당한다.

스카우트운동에서 IST 참여는 단순한 자원봉사를 넘어 국제 협력과 봉사의 실천으로 이해된다. 각국의 스카우트가 함께 행사 운영에 참여함으로써 스카우트 방법의 가치인 협력, 책임, 봉사 정신을 실제 현장에서 구현하는 역할을 한다.' AND sort_order IS 0 AND updated_at IS '2026-03-15 02:10:31';
UPDATE glossary_terms SET term_en='The General Association of the Scouts of China',description_ko='대만을 대표하는 세계스카우트연맹 회원국. 1912년 중화민국에서 시작된 “Scouts of China” 을 역사적으로 계승했으며, 1949년 중화민국 정부의 대만 이전 이후에도 연속성을 유지하기 위해 “Scouts of China” 명칭을 사용하고 있다. 기존 병기 표기: The General Association of the Scouts of China (Taiwan). 회원국 현황의 원문 표기는 The General Association of the Scouts of China이다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=75 AND bucket IS '다' AND term_ko IS '대만 스카우트연맹' AND term_en IS 'The General Association of the Scouts of China (Taiwan)' AND term_fr IS '' AND description_ko IS '대만을 대표하는 세계스카우트연맹 회원국. 1912년 중화민국에서 시작된 “Scouts of China” 을 역사적으로 계승했으며, 1949년 중화민국 정부의 대만 이전 이후에도 연속성을 유지하기 위해 “Scouts of China” 명칭을 사용하고 있다.' AND sort_order IS 0 AND updated_at IS '2026-03-16 08:01:44';
UPDATE glossary_terms SET description_ko='인도네시아를 대표하는 스카우트 연맹의 정식 명칭이다. 세계스카우트연맹의 회원국 조직으로, 인도네시아 전역에서 청소년 교육 프로그램을 운영한다.
‘Gerakan Pramuka’는 ‘Praja Muda Karana’의 약어에서 유래한 명칭으로 “사회를 위해 봉사할 준비가 된 젊은 세대”라는 의미를 담고 있다. 인도네시아에서는 스카우트 활동이 학교 교육과 밀접하게 연계되어 운영되는 특징이 있다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=85 AND bucket IS '아' AND term_ko IS '인도네시아 스카우트연맹' AND term_en IS 'Gerakan Pramuka' AND term_fr IS '' AND description_ko IS '인도네시아를 대표하는 스카우트 연맹의 정식 명칭이다. 세계스카우트연맹의 회원국 조직으로, 인도네시아 전역에서 청소년 교육 프로그램을 운영한다.
‘Gerakan Pramuka’는 ‘Praja Muda Karana’의 약어에서 유래한 명칭으로 “사회를 위해 봉사할 준비가 된 젊은 세대”라는 의미를 담고 있다. 인도네시아에서는 스카우트 활동이 학교 교육과 밀접하게 연계되어 운영되는 특징이 있다.' AND sort_order IS 0 AND updated_at IS '2026-03-16 07:59:17';
UPDATE glossary_terms SET term_ko='말레이시아 스카우트연맹',term_en='Persekutuan Pengakap Malaysia',description_ko='말레이시아 스카우트 연맹의 공식 명칭이다. ‘Pengakap’은 말레이어에서 스카우트(Scout)를 의미하는 단어이다. 말레이시아 스카우트연맹은 세계스카우트연맹의 회원국 조직으로, 말레이시아 전역에서 청소년을 대상으로 스카우트 프로그램을 운영하고 있다. 기존 병기 표기: Persekutuan Pengakap Malaysia (PPM). 회원국 현황의 원문 표기는 Persekutuan Pengakap Malaysia이다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=87 AND bucket IS '마' AND term_ko IS '말레이시아스카우트연맹' AND term_en IS 'Persekutuan Pengakap Malaysia (PPM)' AND term_fr IS '' AND description_ko IS '말레이시아 스카우트 연맹의 공식 명칭이다. ‘Pengakap’은 말레이어에서 스카우트(Scout)를 의미하는 단어이다. 말레이시아 스카우트연맹은 세계스카우트연맹의 회원국 조직으로, 말레이시아 전역에서 청소년을 대상으로 스카우트 프로그램을 운영하고 있다.' AND sort_order IS 0 AND updated_at IS '2026-03-16 07:22:16';
UPDATE glossary_terms SET term_ko='아프가니스탄 스카우트연맹',description_ko='아프가니스탄의 대표 국가스카우트조직(NSO)이다. 원문 조직명은 Afghanistan National Scout Organization이다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=93 AND bucket IS '아' AND term_ko IS '아프가니스탄스카우트연맹' AND term_en IS 'Afghanistan National Scout Organization' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-16 07:32:38';
