UPDATE glossary_terms SET term_ko='브루나이 스카우트연맹',description_ko='브루나이 스카우트연맹의 공식 명칭이다. “Persekutuan”은 연맹 또는 연합, “Pengakap”은 스카우트를 의미하며, ‘브루나이 다루살람 스카우트연맹(Federation of Scouts of Brunei Darussalam)’으로 불린다. 브루나이는 말레이어(Bahasa Melayu)를 국가 공식 언어로 사용하는 말레이 문화권 국가이기 때문에 연맹 명칭도 말레이어 형태로 사용된다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=97 AND bucket IS '바' AND term_ko IS '브루나이스카우트연맹' AND term_en IS 'Persekutuan Pengakap Negara Brunei Darussalam' AND term_fr IS '' AND description_ko IS '브루나이 스카우트연맹의 공식 명칭이다. “Persekutuan”은 연맹 또는 연합, “Pengakap”은 스카우트를 의미하며, ‘브루나이 다루살람 스카우트연맹(Federation of Scouts of Brunei Darussalam)’으로 불린다. 브루나이는 말레이어(Bahasa Melayu)를 국가 공식 언어로 사용하는 말레이 문화권 국가이기 때문에 연맹 명칭도 말레이어 형태로 사용된다.' AND sort_order IS 0 AND updated_at IS '2026-03-16 07:58:46';
