UPDATE glossary_terms SET description_ko='인도의 스카우트 연맹으로, 1950년 여러 스카우트 단체의 통합을 통해 설립되었다. 인도에는 다양한 스카우트 단체가 존재하지만, The Bharat Scouts and Guides는 세계스카우트연맹과 세계걸스카우트연맹에 가입한 인도의 대표 스카우트 연맹으로 인정되고 있다. 참고로 인도는 스카우트 역사에서 “단체가 가장 많이 분열되었다가 다시 통합된 국가 중 하나”이다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=101 AND bucket IS '아' AND term_ko IS '인도 스카우트연맹' AND term_en IS 'The Bharat Scouts and Guides' AND term_fr IS '' AND description_ko IS '인도의 스카우트 연맹으로, 1950년 여러 스카우트 단체의 통합을 통해 설립되었다. 인도에는 다양한 스카우트 단체가 존재하지만, The Bharat Scouts and Guides는 세계스카우트연맹과 세계걸스카우트연맹에 가입한 인도의 대표 스카우트 연맹으로 인정되고 있다. 참고로 인도는 스카우트 역사에서 “단체가 가장 많이 분열되었다가 다시 통합된 국가 중 하나”이다.' AND sort_order IS 0 AND updated_at IS '2026-03-16 08:00:20';
