UPDATE glossary_terms SET description_ko='러시아 스카우트연맹의 영어 명칭이다. “All-Russian”이라는 표현은 러시아 전역을 포괄한다는 의미로, 특정 지역이나 공화국이 아닌 러시아 전체를 대표하는 전국 단위 연맹임을 나타내기 위해 사용된다. 러시아는 다수의 공화국과 자치지역으로 구성된 연방 국가이기 때문에, 국가 단위 청소년 단체나 연맹 명칭에서 “All-Russian”이라는 표현이 널리 사용된다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=114 AND bucket IS '라' AND term_ko IS '러시아 스카우트연맹' AND term_en IS 'All-Russian Scout Association' AND term_fr IS '' AND description_ko IS '러시아 스카우트연맹의 영어 명칭이다. “All-Russian”이라는 표현은 러시아 전역을 포괄한다는 의미로, 특정 지역이나 공화국이 아닌 러시아 전체를 대표하는 전국 단위 연맹임을 나타내기 위해 사용된다. 러시아는 다수의 공화국과 자치지역으로 구성된 연방 국가이기 때문에, 국가 단위 청소년 단체나 연맹 명칭에서 “All-Russian”이라는 표현이 널리 사용된다.' AND sort_order IS 0 AND updated_at IS '2026-03-16 08:02:52';
