UPDATE glossary_terms SET term_ko='솔로몬 제도 스카우트연맹',description_ko='솔로몬 제도의 대표 국가스카우트조직(NSO)이다. 원문 조직명은 Solomon Islands Scout Association이다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=116 AND bucket IS '사' AND term_ko IS '솔로몬아일랜드스카우트연맹' AND term_en IS 'Solomon Islands Scout Association' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-16 07:51:15';
UPDATE glossary_terms SET term_ko='스리랑카 스카우트연맹',description_ko='스리랑카의 대표 국가스카우트조직(NSO)이다. 원문 조직명은 Sri Lanka Scout Association이다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=117 AND bucket IS '사' AND term_ko IS '스리랑카스카우트연맹' AND term_en IS 'Sri Lanka Scout Association' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-16 07:51:24';
UPDATE glossary_terms SET term_en='Ittihodi Scouthoi Tochikiston',description_ko='타지키스탄 스카우트연맹의 명칭이다. “Ittihodi Scouthoi Tochikiston”은 타지크어로 ‘타지키스탄 스카우트 연맹(Association of Scouts of Tajikistan)’을 의미하며, “Associatsia Skautov Tadjikistana”는 같은 의미를 가진 러시아어 표기이다. 타지키스탄에서는 타지크어와 러시아어가 함께 사용되기 때문에 두 언어의 명칭이 병기되는 경우가 많다. 기존 병기 표기: Ittihodi Scouthoi Tochikiston (Associatsia Skautov Tadjikistana - Scout Association of Tajikistan). 회원국 현황의 원문 표기는 Ittihodi Scouthoi Tochikiston이다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=118 AND bucket IS '타' AND term_ko IS '타지키스탄 스카우트연맹' AND term_en IS 'Ittihodi Scouthoi Tochikiston (Associatsia Skautov Tadjikistana - Scout Association of Tajikistan)' AND term_fr IS '' AND description_ko IS '타지키스탄 스카우트연맹의 명칭이다. “Ittihodi Scouthoi Tochikiston”은 타지크어로 ‘타지키스탄 스카우트 연맹(Association of Scouts of Tajikistan)’을 의미하며, “Associatsia Skautov Tadjikistana”는 같은 의미를 가진 러시아어 표기이다. 타지키스탄에서는 타지크어와 러시아어가 함께 사용되기 때문에 두 언어의 명칭이 병기되는 경우가 많다.' AND sort_order IS 0 AND updated_at IS '2026-03-16 08:00:58';
UPDATE glossary_terms SET description_ko='태국의 대표 국가스카우트조직(NSO)이다. 원문 조직명은 National Scout Organization of Thailand이다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=119 AND bucket IS '타' AND term_ko IS '태국 스카우트연맹' AND term_en IS 'National Scout Organization of Thailand' AND term_fr IS '' AND description_ko IS '' AND sort_order IS 0 AND updated_at IS '2026-03-16 08:01:03';
UPDATE glossary_terms SET description_ko='동티모르 스카우트연맹의 포르투갈어 명칭으로, 직역하면 ‘동티모르 스카우트 국가연맹(National Association of Scouts of Timor-Leste)’을 의미한다. 동티모르는 포르투갈어를 공식 언어로 사용하기 때문에 연맹 명칭도 포르투갈어 형태로 사용된다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=120 AND bucket IS '다' AND term_ko IS '동티모르 스카우트연맹' AND term_en IS 'União Nacional dos Escuteiros de Timor-Leste' AND term_fr IS '' AND description_ko IS '동티모르 스카우트연맹의 포르투갈어 명칭으로, 직역하면 ‘동티모르 스카우트 국가연맹(National Association of Scouts of Timor-Leste)’을 의미한다. 동티모르는 포르투갈어를 공식 언어로 사용하기 때문에 연맹 명칭도 포르투갈어 형태로 사용된다.' AND sort_order IS 0 AND updated_at IS '2026-03-16 08:01:49';
UPDATE glossary_terms SET term_ko='베트남 스카우트연맹',description_ko='베트남의 스카우트연맹으로, 2019년 1월 10일 세계스카우트연맹의 제170번째 회원 연맹으로 승인되었다. 베트남은 1957년 베트남 스카우트연맹(Hội Hướng Đạo Việt Nam)을 통해 세계스카우트연맹에 가입했으나, 1975년 베트남 전쟁 이후 활동이 중단되며 회원 지위를 상실하였다. Pathfinder Scouts Vietnam의 가입으로 베트남은 약 44년 만에 세계스카우트연맹에 복귀하게 되었다. 소속 지역연맹: 아시아태평양지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=121 AND bucket IS '바' AND term_ko IS '베트남스카우트연맹' AND term_en IS 'Pathfinder Scouts Vietnam' AND term_fr IS '' AND description_ko IS '베트남의 스카우트연맹으로, 2019년 1월 10일 세계스카우트연맹의 제170번째 회원 연맹으로 승인되었다. 베트남은 1957년 베트남 스카우트연맹(Hội Hướng Đạo Việt Nam)을 통해 세계스카우트연맹에 가입했으나, 1975년 베트남 전쟁 이후 활동이 중단되며 회원 지위를 상실하였다. Pathfinder Scouts Vietnam의 가입으로 베트남은 약 44년 만에 세계스카우트연맹에 복귀하게 되었다.' AND sort_order IS 0 AND updated_at IS '2026-03-16 08:05:36';
UPDATE glossary_terms SET description_ko='세계스카우트연맹의 회원 조직인 국가스카우트조직(NSO)을 뜻한다. 국가나 지역 자체가 아니라 그곳의 스카우트운동을 대표하여 WOSM 회원 자격을 가진 조직이다. 하나의 연맹이 NSO가 되기도 하고, 여러 국가스카우트협회(NSA)가 연합하여 하나의 NSO를 구성하기도 한다. 회원국 현황의 NSO·NSO Federation은 대표 조직이며, 소속 NSA 수와 WOSM 회원 조직 수를 혼동하지 않는다.',updated_at=datetime('now') WHERE id=122 AND bucket IS '하' AND term_ko IS '회원국' AND term_en IS 'National Scout Organisation (NSO)' AND term_fr IS 'Organisations Scoutes Nationales' AND description_ko IS '세계스카우트연맹의 회원국 단위를 의미한다. 한 국가의 스카우트 운동을 대표하며, 세계스카우트연맹(World Organization of the Scout Movement)의 회원 자격을 가진다. 국가에 따라 하나의 스카우트 연맹이 곧 회원국이 되기도 하지만, 여러 스카우트 연맹이 함께 하나의 회원국 구조를 이루는 경우도 있다.' AND sort_order IS 0 AND updated_at IS '2026-03-17 01:12:13';
UPDATE glossary_terms SET description_ko='국가스카우트협회(NSA)는 한 국가의 스카우트운동을 구성하는 개별 협회·연맹이다. 복수 협회가 연합한 국가에서는 여러 NSA가 하나의 대표 국가스카우트조직(NSO)을 구성할 수 있다. 회원국 현황에서 NSA로 분류된 조직을 독립된 WOSM 회원국 수에 각각 더하지 않는다. 프랑스·이탈리아·독일 등에서 대표 NSO와 소속 NSA를 함께 확인할 수 있다.',updated_at=datetime('now') WHERE id=123 AND bucket IS '사' AND term_ko IS '스카우트 협회' AND term_en IS 'National Scout Association (NSA)' AND term_fr IS '' AND description_ko IS '한 국가의 스카우트 운동을 구성하는 개별 스카우트 연맹을 의미한다. 복수 연맹 구조를 가진 국가에서는 여러 NSA가 함께 하나의 회원국(NSO)을 구성한다. 예를 들어 이탈리아에서는 AGESCI와 CNGEI가 각각 NSA이며 공동으로 하나의 회원국 구조를 이루고 있다. 프랑스, 덴마크, 벨기에 등에서도 여러 스카우트 연맹이 함께 회원국 체계를 구성하는 사례가 존재한다.' AND sort_order IS 0 AND updated_at IS '2026-03-17 01:13:10';
UPDATE glossary_terms SET description_ko='엘살바도르의 스카우트 운동을 대표하는 연맹으로, 명칭은 스페인어를 기반으로 한다. ‘Asociación’은 연맹 또는 협회를 의미하며, 전체적으로는 ‘엘살바도르의 스카우트 연맹’이라는 뜻을 가진다. 엘살바도르의 공식 언어가 스페인어인 만큼, 연맹의 공식 문서와 프로그램 역시 스페인어를 중심으로 운영된다. 소속 지역연맹: 인터아메리카지역연맹. 명칭·회원 구분 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',updated_at=datetime('now') WHERE id=124 AND bucket IS '아' AND term_ko IS '엘살바도르 스카우트연맹' AND term_en IS 'Asociación de Scouts de El Salvador' AND term_fr IS '' AND description_ko IS '엘살바도르의 스카우트 운동을 대표하는 연맹으로, 명칭은 스페인어를 기반으로 한다. ‘Asociación’은 연맹 또는 협회를 의미하며, 전체적으로는 ‘엘살바도르의 스카우트 연맹’이라는 뜻을 가진다. 엘살바도르의 공식 언어가 스페인어인 만큼, 연맹의 공식 문서와 프로그램 역시 스페인어를 중심으로 운영된다.' AND sort_order IS 0 AND updated_at IS '2026-03-19 01:58:44';
UPDATE glossary_terms SET term_ko='세계우애의 날',description_ko='세계걸가이드·걸스카우트 운동이 매년 2월 22일 기념하는 국제 우애의 날이다. 1926년 시작되었으며, 다른 나라의 걸가이드·걸스카우트를 생각하고 우정과 연대를 나누는 날이다. 같은 날 스카우트운동에서 기념하는 창립자의 날(Founder’s Day)과 구분한다. 2026년은 세계우애의 날 100주년이며 주제는 우정(Friendship)이다.',updated_at=datetime('now') WHERE id=125 AND bucket IS '사' AND term_ko IS '세계우애' AND term_en IS 'World Thinking Day' AND term_fr IS '' AND description_ko IS '매년 2월 22일에 기념되는 국제 활동일로, 스카우트와 걸가이드 구성원 간의 국제적 연대와 상호 이해를 목적으로 한다. 이 날짜는 로버트 베이든-파월과 올레이브 베이든-파월의 생일에서 유래하였다. 세계스카우트연맹과 세계걸가이드걸스카우트연맹이 공동으로 기념하며, 매년 주제를 설정하여 각 회원국에서 관련 프로그램과 활동을 운영한다.' AND sort_order IS 0 AND updated_at IS '2026-03-19 06:31:25';
UPDATE glossary_terms SET description_ko='일본스카우트연맹(Scout Association of Japan)이 매년 개최하는 전국 규모의 스카우트 행사이다. 스카우트 운동의 의의를 사회에 널리 알리고, 회원 간의 교류와 정보교환을 촉진하기 위해 개최된다. 일본어 명칭은 「全国大会(ぜんこくたいかい, Zenkoku Taikai)」이다.

전국대회는 매년 일본의 47개 도도부현이 순환 개최하며, 약 1,000명 이상의 지도자와 대원, 일반 참가자가 함께 참여한다. 행사 기간 동안 개회식, 포상수여식, 전국스카우트교육회의, 스카우팅 엑스포(SCOUTING EXPO), 분야별 회의 및 설명회, 교환회(交歓会) 등이 운영된다.

또한 스카우트 운동을 지역사회와 일반 대중에게 소개하는 사회적 홍보 기능을 수행하며, 일본연맹 회원으로서의 정체성과 소속감을 높이는 역할을 한다. 아울러 차기 개최지와 일본잼버리 등 주요 국가 행사를 홍보하고, 전국의 지도자와 대원들이 교류하며 정보를 공유하는 장으로 활용되고 있다.',updated_at=datetime('now') WHERE id=135 AND bucket IS '자' AND term_ko IS '전국대회(全国大会)' AND term_en IS 'National Scout Convention' AND term_fr IS '' AND description_ko IS '일본스카우트연맹(Boy Scouts of Japan)이 매년 개최하는 전국 규모의 스카우트 행사이다. 스카우트 운동의 의의를 사회에 널리 알리고, 회원 간의 교류와 정보교환을 촉진하기 위해 개최된다. 일본어 명칭은 「全国大会(ぜんこくたいかい, Zenkoku Taikai)」이다.

