INSERT INTO glossary_terms (bucket,term_ko,term_en,term_fr,description_ko,sort_order) SELECT '가','','Norges Speiderforbund','','노르웨이의 국가스카우트협회(NSA)로 회원국 현황에 기재된 조직이다. 원문 명칭은 Norges Speiderforbund이다. 대표 NSO 아래의 소속 협회와 독립된 WOSM 회원 조직을 구분한다. 확인된 한국어 공식 명칭이 없어 원문명을 유지한다. 소속 지역연맹: 유럽지역연맹. 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',0 WHERE NOT EXISTS (SELECT 1 FROM glossary_terms WHERE term_en='Norges Speiderforbund' OR term_fr='Norges Speiderforbund');
