INSERT INTO glossary_terms (bucket,term_ko,term_en,term_fr,description_ko,sort_order) SELECT '자','잠비아 스카우트연맹','Zambia Scouts Association','','잠비아의 대표 국가스카우트조직이다. 회원국 현황의 분류는 NSO이며 원문 조직명은 Zambia Scouts Association이다. 한국어 표기는 국가별 조직을 찾기 위한 안내 명칭이다. 소속 지역연맹: 아프리카지역연맹. 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',0 WHERE NOT EXISTS (SELECT 1 FROM glossary_terms WHERE term_en='Zambia Scouts Association' OR term_fr='Zambia Scouts Association');
INSERT INTO glossary_terms (bucket,term_ko,term_en,term_fr,description_ko,sort_order) SELECT '자','짐바브웨 스카우트연맹','The Scout Association of Zimbabwe','','짐바브웨의 대표 국가스카우트조직이다. 회원국 현황의 분류는 NSO이며 원문 조직명은 The Scout Association of Zimbabwe이다. 한국어 표기는 국가별 조직을 찾기 위한 안내 명칭이다. 소속 지역연맹: 아프리카지역연맹. 기준: BP미디어 세계연맹 회원국 현황(2026-10-08 확인).',0 WHERE NOT EXISTS (SELECT 1 FROM glossary_terms WHERE term_en='The Scout Association of Zimbabwe' OR term_fr='The Scout Association of Zimbabwe');
INSERT INTO glossary_terms (bucket,term_ko,term_en,term_fr,description_ko,sort_order) SELECT '라','로버스카우트 (로버대)','Rover Scouts','','청년 연령층을 위한 스카우트 단계이다. 스스로 기획하는 모험, 공동체 봉사와 사회 참여 등을 통해 성장을 이어 간다. 연령과 운영 방식은 국가연맹별로 다르다.',0 WHERE NOT EXISTS (SELECT 1 FROM glossary_terms WHERE term_en='Rover Scouts' OR term_fr='Rover Scouts');
INSERT INTO glossary_terms (bucket,term_ko,term_en,term_fr,description_ko,sort_order) SELECT '가','국가스카우트연합','National Scout Federation (NSO Federation)','','여러 국가스카우트협회(NSA)가 연합하여 한 국가의 대표 NSO를 구성하는 조직 형태이다. 회원국 현황의 NSO Federation과 그 아래 소속 NSA를 구분하여 읽는다.',0 WHERE NOT EXISTS (SELECT 1 FROM glossary_terms WHERE term_en='National Scout Federation (NSO Federation)' OR term_fr='National Scout Federation (NSO Federation)');
INSERT INTO glossary_terms (bucket,term_ko,term_en,term_fr,description_ko,sort_order) SELECT '차','창립자의 날','Founder''s Day','','스카우트운동에서 창립자 로버트 베이든파월의 생일인 2월 22일 기념하는 날이다. 스카우트 정신과 봉사·우정을 되새긴다. 같은 날 걸가이드·걸스카우트 운동이 기념하는 세계우애의 날(World Thinking Day)과 구분한다.',0 WHERE NOT EXISTS (SELECT 1 FROM glossary_terms WHERE term_en='Founder''s Day' OR term_fr='Founder''s Day');
INSERT INTO glossary_terms (bucket,term_ko,term_en,term_fr,description_ko,sort_order) SELECT '아','아프리카지역연맹','Africa Scout Region','','세계스카우트연맹의 지역 조직 가운데 하나로, 해당 지역 국가스카우트조직들의 협력과 성장을 지원한다. BP미디어 회원국 현황의 Africa 지역 분류와 연결되며, 지역 총회·지역 이사회·지역 사무국은 서로 다른 역할을 맡는다.',0 WHERE NOT EXISTS (SELECT 1 FROM glossary_terms WHERE term_en='Africa Scout Region' OR term_fr='Africa Scout Region');
